"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import ThemeToggle from "../theme-toggle";
import DeveloperCredit from "../developer-credit";
import { Activity, ArrowDownRight, ArrowLeft, ArrowRight, BookOpen, Check, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Code2, Database, FileSearch, Filter, GitBranch, Layers, LoaderCircle, LockKeyhole, Monitor, Search, ShieldCheck, Terminal, X } from "lucide-react";

type CaseRow={slug:string;id:string;title:string;difficulty:string;learning_objective:string;completed:boolean;delta_count:number;item_count?:number;locked?:boolean};
type Delta={id:string;category:string;operation:string;object_key:string;before:Record<string,unknown>|null;after:Record<string,unknown>|null;before_snapshot_id?:string;after_snapshot_id?:string;window:{start:string;end:string}};
type CSGTransition={id:string;source:"csg";host:string;observed_at:string;category:string;object_key:string;transition:string;before:Record<string,unknown>|null;after:Record<string,unknown>|null};
type InvestigationItem={id:string;kind:"delta"|"transition";title:string;category:string;object_key:string;transition_ids:string[];delta_id?:string};
type Snapshot={snapshot_id:string;host_id:string;observed_at:string;objects_count:number;counts:Record<string,number>;collector_health:Record<string,string>};
type EventRow={id:string;timestamp:string;host_name:string;event_code:string;event_type:string;provider:string;object_key:string;service_name?:string;process_name?:string;registry_key?:string;normalized:Record<string,any>;provenance:string;raw?:Record<string,any>};
type BriefingSection={name:string;description:string};
type CaseBriefing={research_context?:string;scenario:string;csg_observed:string;what_this_case_teaches:string;technical_context:string;evidence_available:BriefingSection[];your_task:string};
type CaseData={id:string;slug:string;title:string;difficulty:string;learning_objective:string;host:string;briefing:CaseBriefing;variant:string;target:string;deltas:Delta[];investigations:InvestigationItem[];exercise_ids:string[];timeline_start:string;timeline_end:string};
const labels:Record<string,string>={service:"Services",process:"Processes",listener:"Listeners",scheduled_task:"Scheduled tasks",registry_autorun:"Registry autoruns",privileged_group_member:"Administrators",defender_exclusion:"Defender exclusions"};
const statuses=["CONSISTENT","PARTIALLY_EXPLAINED","UNEXPLAINED","CONTRADICTED","INSUFFICIENT_EVIDENCE"];
const date=(v:string,seconds=false)=>new Date(v).toLocaleString("en-US",{month:"short",day:"2-digit",hour:"2-digit",minute:"2-digit",...(seconds?{second:"2-digit"}:{})});
const toLocalDateTime=(v:string)=>{const d=new Date(v);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,19)};
const fromLocalDateTime=(v:string)=>{const d=new Date(v);return Number.isNaN(d.getTime())?null:d.toISOString()};
const eventTypes=["service_modified","service_created","service_state_change","process_start","process_exit","powershell_script_block","defender_configuration_changed","registry_value_set","scheduled_task_created","network_activity","logon_success","dns_query","file_activity"];
const eventTypeLabels:Record<string,string>={service_modified:"Service configuration change · 7040",service_state_change:"Service runtime state · 7036"};
const eventTypeLabel=(type:string)=>eventTypeLabels[type]||type.replaceAll("_"," ");
const eventCategories=[{value:"service",label:"Service"},{value:"process",label:"Process"},{value:"powershell",label:"PowerShell"},{value:"defender",label:"Defender"},{value:"network",label:"Network"},{value:"registry",label:"Registry"},{value:"scheduled",label:"Scheduled task"},{value:"logon",label:"Logon"},{value:"dns",label:"DNS"},{value:"file",label:"File"}];
const eventProviders=["Microsoft-Windows-Sysmon","Microsoft-Windows-PowerShell","Microsoft-Windows-Windows Defender","Service Control Manager","Microsoft-Windows-TaskScheduler","Microsoft-Windows-Security-Auditing"];
const eventCodes=["1","3","5","11","13","22","106","4624","4104","5007","5154","7036","7040","7045"];
const filterHosts=(host:string)=>[host,...Array.from({length:8},(_,i)=>`WIN-OPS-${String(i+1).padStart(2,"0")}`)];
const journeyStages=[
  {key:"briefing",title:"Case briefing",short:"Get oriented",icon:"01"},
  {key:"csg",title:"CSG state",short:"Compare snapshots",icon:"02"},
  {key:"wazuh",title:"Wazuh events",short:"Search evidence",icon:"03"},
  {key:"reconcile",title:"Reconcile",short:"Explain your finding",icon:"04"},
] as const;
type JourneyStage=typeof journeyStages[number]["key"];

function transitionMarkers(transitions:CSGTransition[],start:string,end:string){
  const from=Date.parse(start),to=Date.parse(end),lanes:number[]=[];
  const buckets=new Map<string,CSGTransition[]>();
  for(const transition of transitions){
    const minute=new Date(Math.floor(Date.parse(transition.observed_at)/60000)*60000).toISOString();
    buckets.set(minute,[...(buckets.get(minute)||[]),transition]);
  }
  return Array.from(buckets.entries()).sort(([left],[right])=>Date.parse(left)-Date.parse(right)).map(([time,records])=>{
    const ratio=to>from?(Date.parse(time)+30000-from)/(to-from):.5;
    const position=Math.max(3,Math.min(97,3+ratio*94));
    let lane=lanes.findIndex(previous=>Math.abs(position-previous)>7);
    if(lane===-1)lane=lanes.length;
    lanes[lane]=position;
    return {time,records,position,lane};
  });
}
const statusLabel=(status:string)=>({CONSISTENT:"Consistent",PARTIALLY_EXPLAINED:"Partially explained",UNEXPLAINED:"Unexplained",CONTRADICTED:"Contradicted",INSUFFICIENT_EVIDENCE:"Insufficient evidence"} as Record<string,string>)[status]||status;
const snapshotName=(index:number)=>`Snapshot ${String.fromCharCode(65+Math.max(0,index))}`;
function archivePresetRange(preset:string,start:string,end:string){const endMs=new Date(end).getTime(),startMs=new Date(start).getTime(),minutes=preset==="last5"?5:preset==="last15"?15:preset==="last30"?30:preset==="last60"?60:0;return minutes?{start:new Date(Math.max(startMs,endMs-minutes*60000)).toISOString(),end:new Date(endMs).toISOString()}:{start,end}}
function minuteSlots(start:string,end:string,histogram:{time:string;count:number}[]){const from=Math.floor(new Date(start).getTime()/60000)*60000,to=new Date(end).getTime(),counts=new Map(histogram.map(x=>[Math.floor(new Date(x.time).getTime()/60000)*60000,x.count]));const slots=[];for(let t=from;t<to;t+=60000)slots.push({time:new Date(t).toISOString(),end:new Date(Math.min(t+60000,to)).toISOString(),count:counts.get(t)||0});return slots}
const api=async(path:string,init?:RequestInit)=>{const res=await fetch(`/api${path}`,{credentials:"include",...init});const body=await res.json().catch(()=>({}));if(!res.ok)throw new Error(body.detail||"Request failed");return body};

export default function Lab(){
  const router=useRouter();
  const [student,setStudent]=useState<{display_name:string;variant:string}|null>(null);
  const [cases,setCases]=useState<CaseRow[]>([]);
  const [slug,setSlug]=useState("");
  const [caseData,setCaseData]=useState<CaseData|null>(null);
  const [timeline,setTimeline]=useState<{snapshots:Snapshot[];deltas:Delta[];transitions:CSGTransition[];investigations:InvestigationItem[];submissions:Record<string,any>}|null>(null);
  const [view,setView]=useState<"briefing"|"csg"|"wazuh"|"reconcile">("briefing");
  const [deltaId,setDeltaId]=useState("");
  const [snapshotId,setSnapshotId]=useState("");
  const [expandedDeltaId,setExpandedDeltaId]=useState("");
  const [focusedTransitionId,setFocusedTransitionId]=useState("");
  const [focusedCSGMinute,setFocusedCSGMinute]=useState("");
  const [category,setCategory]=useState("");
  const [inventory,setInventory]=useState<any>(null);
  const [inventoryQuery,setInventoryQuery]=useState("");
  const [inventoryPage,setInventoryPage]=useState(1);
  const [query,setQuery]=useState("");
  const [eventType,setEventType]=useState("");
  const [eventCategory,setEventCategory]=useState("");
  const [eventCode,setEventCode]=useState("");
  const [provider,setProvider]=useState("");
  const [hostFilter,setHostFilter]=useState("");
  const [events,setEvents]=useState<any>(null);
  const [timeRange,setTimeRange]=useState<{start:string;end:string}|null>(null);
  const [timeDraft,setTimeDraft]=useState({start:"",end:""});
  const [timePreset,setTimePreset]=useState("full");
  const [eventDetail,setEventDetail]=useState<EventRow|null>(null);
  const [detailSource,setDetailSource]=useState<"results"|"tray">("results");
  const detailRequestId=useRef(0);
  const [tray,setTray]=useState<EventRow[]>([]);
  const [classification,setClassification]=useState("");
  const [explanation,setExplanation]=useState("");
  const [reveal,setReveal]=useState<any>(null);
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState("");
  const searchRequestId=useRef(0);
  const evidenceContext=useRef("");
  evidenceContext.current=`${slug}:${deltaId}`;
  const activeDelta=useMemo(()=>timeline?.deltas.find(d=>d.id===deltaId)||null,[timeline,deltaId]);
  const activeInvestigation=useMemo(()=>timeline?.investigations?.find(item=>item.id===deltaId)||null,[timeline,deltaId]);
  const activeTransitions=useMemo(()=>timeline?.transitions?.filter(t=>activeInvestigation?.transition_ids.includes(t.id))||[],[timeline,activeInvestigation]);
  const activeDeltaBeforeIndex=activeDelta?Math.max(0,timeline?.snapshots.findIndex(s=>s.snapshot_id===activeDelta.before_snapshot_id)??0):0;
  const activeDeltaAfterIndex=activeDelta?Math.max(0,timeline?.snapshots.findIndex(s=>s.snapshot_id===activeDelta.after_snapshot_id)??1):1;

  const loadCore=useCallback(async(nextSlug:string)=>{
    searchRequestId.current+=1;detailRequestId.current+=1;setBusy(true);setError("");setEvents(null);setInventory(null);
    try{
      const [c,t]=await Promise.all([api(`/cases/${nextSlug}`),api(`/cases/${nextSlug}/timeline`)]);
      setCaseData(c);setTimeline(t);setSlug(nextSlug);setDeltaId(t.investigations[0]?.id||t.deltas[0]?.id||"");setSnapshotId(t.snapshots[0]?.snapshot_id||"");setExpandedDeltaId("");setFocusedTransitionId("");setFocusedCSGMinute("");setTray([]);setReveal(null);setClassification("");setExplanation("");setTimeRange({start:c.timeline_start,end:c.timeline_end});setTimeDraft({start:toLocalDateTime(c.timeline_start),end:toLocalDateTime(c.timeline_end)});setTimePreset("full");setQuery("");setEventType("");setEventCategory("");setEventCode("");setProvider("");setHostFilter("");setEventDetail(null);setCategory("");setInventoryQuery("");setInventoryPage(1);
      if(!t.deltas.length&&!t.transitions.length)setView("briefing");
    }catch(e){setError(e instanceof Error?e.message:"Unable to load case")}
    finally{setBusy(false)}
  },[]);
  useEffect(()=>{(async()=>{try{const [me,c]=await Promise.all([api("/sessions/me"),api("/cases")]);setStudent(me);setCases(c);const initial=c.find((x:CaseRow)=>!x.completed)||c[c.length-1];if(initial)await loadCore(initial.slug);}catch{router.replace("/")}})()},[loadCore,router]);
  useEffect(()=>{if(!slug||!snapshotId)return;let active=true;api(`/cases/${slug}/snapshots/${snapshotId}?category=${encodeURIComponent(category)}&q=${encodeURIComponent(inventoryQuery)}&page=${inventoryPage}&page_size=100`).then(d=>active&&setInventory(d)).catch(()=>{});return()=>{active=false}},[slug,snapshotId,category,inventoryQuery,inventoryPage]);
  const search=useCallback(async(page=1)=>{if(!slug)return;const requestId=++searchRequestId.current;detailRequestId.current+=1;setEventDetail(null);setBusy(true);setError("");try{const params=new URLSearchParams({slug,q:query,event_type:eventType,page:String(page),page_size:"100"});if(eventCategory)params.set("event_category",eventCategory);if(eventCode)params.set("event_code",eventCode);if(provider)params.set("provider",provider);if(hostFilter)params.set("host",hostFilter);if(timeRange){params.set("start",timeRange.start);params.set("end",timeRange.end)}const result=await api(`/events?${params}`);if(requestId===searchRequestId.current)setEvents(result);}catch(e){if(requestId===searchRequestId.current)setError(e instanceof Error?e.message:"Search failed")}finally{if(requestId===searchRequestId.current)setBusy(false)}},[slug,query,eventType,eventCategory,eventCode,provider,hostFilter,timeRange]);
  useEffect(()=>{if(view!=="wazuh"||!slug)return;const timer=window.setTimeout(()=>void search(1),350);return()=>window.clearTimeout(timer)},[view,slug,query,eventType,eventCategory,eventCode,provider,hostFilter,timeRange,search]);
  function applyTimeRange(start:string,end:string,preset="custom"){setTimeRange({start,end});setTimeDraft({start:toLocalDateTime(start),end:toLocalDateTime(end)});setTimePreset(preset)}
  function chooseTimePreset(preset:string){if(!caseData)return;setTimePreset(preset);if(preset!=="custom"){const range=archivePresetRange(preset,caseData.timeline_start,caseData.timeline_end);applyTimeRange(range.start,range.end,preset)}}
  function editTimeBound(bound:"start"|"end",value:string){const next={...timeDraft,[bound]:value};setTimeDraft(next);const start=fromLocalDateTime(next.start),end=fromLocalDateTime(next.end);if(start&&end&&Date.parse(start)<=Date.parse(end)){setTimeRange({start,end});setTimePreset("custom")}}
  function clearEventFilters(){if(!caseData)return;setQuery("");setEventType("");setEventCategory("");setEventCode("");setProvider("");setHostFilter("");applyTimeRange(caseData.timeline_start,caseData.timeline_end,"full")}
  const refreshTray=useCallback(async(id:string)=>{if(!slug||!id)return;try{const d=await api(`/cases/${slug}/evidence?delta_id=${encodeURIComponent(id)}`);if(evidenceContext.current===`${slug}:${id}`)setTray(d.items||[])}catch{}},[slug]);
  useEffect(()=>{if(deltaId)void refreshTray(deltaId)},[deltaId,refreshTray]);
  useEffect(()=>{if(!slug||!deltaId)return;let active=true;api(`/cases/${slug}/submissions/${deltaId}`).then(d=>{if(active){setClassification(d.student_classification||"");setExplanation(d.explanation||"");setReveal(d)}}).catch(()=>active&&setReveal(null));return()=>{active=false}},[slug,deltaId]);
  const chartItems=useMemo(()=>caseData?minuteSlots(caseData.timeline_start,caseData.timeline_end,events?.histogram||[]):[],[caseData?.timeline_start,caseData?.timeline_end,events?.histogram]);

  async function inspectEvent(id:string,source:"results"|"tray"="results"){
    const requestId=++detailRequestId.current;
    try{const record=await api(`/events/${id}`);if(requestId===detailRequestId.current){setDetailSource(source);setEventDetail(record)}}catch(e){setError(e instanceof Error?e.message:"Unable to open event")}
  }
  function closeEvent(){detailRequestId.current+=1;setEventDetail(null)}
  function filterFromEvent(field:"host"|"event_code",value:string){if(field==="host")setHostFilter(value);else setEventCode(value);closeEvent();showStage("wazuh")}

  async function toggleEvidence(e:EventRow){if(!caseData)return;const selected=tray.some(x=>x.id===e.id);try{await api(`/cases/${slug}/evidence/${deltaId}/${e.id}`,{method:selected?"DELETE":"PUT"});await refreshTray(deltaId)}catch(err){setError(err instanceof Error?err.message:"Evidence update failed")}}
  async function submit(){if(!classification||explanation.trim().length<20)return;setBusy(true);setError("");try{const result=await api(`/cases/${slug}/submissions`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({delta_id:deltaId,classification,explanation})});setReveal(result);const fresh=await api("/cases");setCases(fresh)}catch(e){setError(e instanceof Error?e.message:"Submission failed")}finally{setBusy(false)}}
  async function nextCase(next:string){await loadCore(next);setView("briefing")}
  function showStage(next:JourneyStage){setView(next);window.scrollTo({top:0,behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"})}
  function selectInvestigation(id:string){if(id===deltaId)return;setDeltaId(id);setReveal(null);setClassification("");setExplanation("");setTray([])}
  function focusCSGTransition(id?:string){if(!id){showStage("csg");return}setView("csg");setFocusedTransitionId(id);window.requestAnimationFrame(()=>window.requestAnimationFrame(()=>document.getElementById(`csg-transition-${id}`)?.scrollIntoView({behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth",block:"center"})))}
  if(!student||!caseData||!timeline)return <main className="loading-screen"><LoaderCircle className="spin"/> Opening your case…</main>;
  const selectedEventIds=new Set(tray.map(e=>e.id));
  const snapshot=timeline.snapshots.find(x=>x.snapshot_id===snapshotId);
  const selectedSnapshotIndex=Math.max(0,timeline.snapshots.findIndex(x=>x.snapshot_id===snapshotId));
  const snapshotBefore=timeline.snapshots[0];
  const snapshotAfter=timeline.snapshots[timeline.snapshots.length-1];
  const observationMinutes=Math.max(0,Math.round((Date.parse(snapshotAfter?.observed_at||caseData.timeline_end)-Date.parse(snapshotBefore?.observed_at||caseData.timeline_start))/60000));
  const observationHours=Math.floor(observationMinutes/60);
  const observationRemainder=observationMinutes%60;
  const observationLabel=observationMinutes>=60?`${observationHours}h${observationRemainder?` ${observationRemainder}m`:""} observation interval`:`${observationMinutes}m observation interval`;
  const primaryCounts=Object.entries(snapshot?.counts||{}).filter(([,n])=>Number(n)>0);
  const markers=transitionMarkers(timeline.transitions,snapshotBefore?.observed_at||caseData.timeline_start,snapshotAfter?.observed_at||caseData.timeline_end);
  const markerLanes=Math.max(0,...markers.map(marker=>marker.lane));
  const selectedCSGMinute=markers.find(marker=>marker.time===focusedCSGMinute);
  const collectorStates=Object.values(snapshot?.collector_health||{});
  const collectorsHealthy=collectorStates.length>0&&collectorStates.every(state=>state==="healthy");
  
  const completedCases=cases.filter(c=>c.completed).length;
  const availableCases=cases.filter(c=>!c.locked&&!c.completed).length;
  const caseProgress=cases.length?Math.round(completedCases/cases.length*100):0;

  return <main className="lab-shell">
    <header className="lab-topbar">
      <a className="lab-brand" href="/lab"><span><ShieldCheck size={18}/></span><b>CSG <strong>Endpoint Detective</strong></b></a>
      <div className="top-crumb"><span>CY530 FIELD LAB</span><ChevronRight size={13}/><b>INVESTIGATION WORKSPACE</b></div>
      <div className="top-user"><ThemeToggle/><span className="user-avatar">{student.display_name.slice(0,1).toUpperCase()}</span><b>{student.display_name}</b></div>
    </header>
    <div className="lab-frame">
      <aside className="case-rail">
        <div className="rail-section-label">CASE QUEUE <span>{String(cases.length).padStart(2,"0")}</span></div>
        <div className="case-progress-card"><div><span>LAB PROGRESS</span><b>{completedCases}<small> / {cases.length}</small></b></div><div className="case-progress-track"><i style={{width:`${caseProgress}%`}}/></div><small>{completedCases===cases.length?"All cases complete":`${availableCases} case${availableCases===1?"":"s"} ready to investigate`}</small></div>
        {cases.map((c,i)=><button key={c.slug} disabled={c.locked} className={`case-rail-item ${c.slug===slug?"active":""} ${c.locked?"locked":""}`} onClick={()=>void nextCase(c.slug)}>
          <span className={`case-num ${c.completed?"done":""}`}>{c.completed?<Check size={13}/>:String(i+1).padStart(2,"0")}</span><span className="case-rail-copy"><b>{c.title}</b><small>{c.locked?"LOCKED":`${c.difficulty.toUpperCase()} · ${c.item_count??c.delta_count} INVESTIGATION ITEMS`}</small></span><ChevronRight size={14}/>
        </button>)}
        <div className="rail-bottom-card"><div className="rail-mini-title"><Activity size={13}/> SESSION STATUS</div><div className="rail-session-line"><i/> Signed in</div><div className="rail-session-meta">Variant {student.variant}</div><a href="/instructor">Instructor console <ArrowRight size={12}/></a></div>
      </aside>

      <section className="workspace">
        <div className="workspace-heading">
          <div><div className="breadcrumb-label">CASE FILE <span>/</span> {caseData.id.toUpperCase()}</div><h1>{caseData.title}</h1><div className="heading-meta"><span className="difficulty-chip">{caseData.difficulty}</span><span><Monitor size={13}/>{caseData.host}</span><span><Clock3 size={13}/>{date(caseData.timeline_start)} — {date(caseData.timeline_end)}</span></div></div>
          <div className="case-actions"><span className="saving-state"><Database size={13}/> Variant {student.variant}</span><button className="icon-action" aria-label="Return to case briefing" title="Case briefing" onClick={()=>showStage("briefing")}><CircleHelp size={17}/></button></div>
        </div>
        <nav className="workspace-tabs" aria-label="Investigation sections">
          {journeyStages.map((stage,i)=><button key={stage.key} className={`journey-tab ${view===stage.key?"active":""}`} aria-current={view===stage.key?"step":undefined} onClick={()=>showStage(stage.key)}><span className="tab-index">0{i+1}</span><span className="journey-tab-copy"><b>{stage.title}</b><small>{stage.short}</small></span>{stage.key==="wazuh"&&tray.length>0&&<span className="tab-count">{tray.length}</span>}</button>)}
          
        </nav>

        {error&&<div className="notice-error"><X size={15}/>{error}<button onClick={()=>setError("")} aria-label="Dismiss"><X size={14}/></button></div>}

        {view==="briefing"&&<div className="briefing-layout">
          <article className="briefing-main panel">
            <div className="section-kicker"><FileSearch size={15}/> CASE BRIEFING</div>
            <h2>State and events.</h2>
            <p className="research-intro">{caseData.briefing.research_context||"CyberStateGuardian (CSG) captures endpoint state and records changes between snapshots. Wazuh is an open-source SIEM configured here to collect Windows and Sysmon event logs. The research question: how well do those independently collected logs explain the changes CSG observes?"}</p>
            <h3 className="case-story-heading">The case</h3>
            <p className="briefing-lead">{caseData.briefing.scenario}</p>
            <div className="briefing-task"><span className="side-label">YOUR TASK</span><p>{caseData.briefing.your_task}</p></div>
            <div className="briefing-start"><button className="primary-action" onClick={()=>showStage("csg")}>Inspect CSG state <ArrowRight size={17}/></button><span>{timeline.investigations.length} investigation item{timeline.investigations.length===1?"":"s"}</span></div>
            <details className="briefing-notes"><summary><BookOpen size={16}/><span>Background for this case</span><ChevronDown size={16}/></summary><div><h3>Technical context</h3><p>{caseData.briefing.technical_context}</p><h3>What you’ll practice</h3><p>{caseData.briefing.what_this_case_teaches}</p></div></details>
            <details className="briefing-notes"><summary><Database size={16}/><span>Available evidence</span><ChevronDown size={16}/></summary><div className="brief-evidence-list">{caseData.briefing.evidence_available.map(item=><div key={item.name}><b>{item.name}</b><p>{item.description}</p></div>)}</div></details>
          </article>
          <aside className="briefing-side">
            <BriefingEvidenceMap key={slug} snapshots={timeline.snapshots} deltas={timeline.deltas} onOpenCSG={focusCSGTransition} onOpenWazuh={()=>showStage("wazuh")}/>
          </aside>
        </div>}

        {view==="csg"&&<div className="state-view">
          <div className="view-intro"><div><div className="section-kicker">CYBERSTATEGUARDIAN <span>· STATE RECONCILIATION</span></div><h2>Endpoint state timeline</h2><p>Compare the inventories, then check what CSG recorded between them.</p></div><div className="source-badge"><Database size={14}/> CSG STATE EVIDENCE</div></div>
          <section className="timeline-card panel">
            <div className="timeline-title"><div><span className="side-label">CSG OBSERVATION WINDOW</span><b>{caseData.host}</b></div><span className={`health-chip ${collectorsHealthy?"":"review"}`}><i/>{collectorsHealthy?"Collectors healthy":"Check collector status"}</span></div>
            <div className="timeline-track" style={{minHeight:`${100+markerLanes*30}px`}}>
              <div className="track-line"/>
              {timeline.snapshots.map((capture,index)=>{const first=index===0,last=index===timeline.snapshots.length-1,position=timeline.snapshots.length>1?3+(index/(timeline.snapshots.length-1))*94:50;return <div key={capture.snapshot_id} className={`timeline-node ${last?"focus":""} ${!first&&!last?"middle":""}`} style={first?{left:`${position}%`}:last?{left:"auto",right:"3%"}:{left:`${position}%`}}><span className="node-dot"/><b>{snapshotName(index).toUpperCase()}</b><small>{date(capture.observed_at)}</small></div>})}
              <div className="timeline-range">{observationLabel}</div>
              {markers.map(({time,records,position,lane},index)=><button type="button" key={time} className={`timeline-transition-marker ${focusedCSGMinute===time||records.some(record=>record.id===focusedTransitionId)?"focused":""}`} style={{left:`${position}%`,top:`${55+lane*30}px`,animationDelay:`${index*45}ms`}} title={`${records.length} CSG change${records.length===1?"":"s"} · ${date(time)}`} aria-label={`Inspect ${records.length} CSG change${records.length===1?"":"s"} from ${date(time)}`} aria-pressed={focusedCSGMinute===time} onClick={()=>setFocusedCSGMinute(focusedCSGMinute===time?"":time)}><i style={{height:`${24+lane*30}px`}}/><span>+{records.length}</span></button>)}
            </div>
            {markers.length>0&&<p className="timeline-legend">Markers show CSG changes per minute. Select one to inspect.</p>}
            {selectedCSGMinute&&<div className="csg-cluster-details" role="region" aria-label="CSG changes in selected minute"><div><span>{date(selectedCSGMinute.time)} · {selectedCSGMinute.records.length} recorded change{selectedCSGMinute.records.length===1?"":"s"}</span><button aria-label="Clear timeline selection" onClick={()=>setFocusedCSGMinute("")}><X size={15}/></button></div>{selectedCSGMinute.records.map(transition=><button key={transition.id} onClick={()=>focusCSGTransition(transition.id)}><time>{date(transition.observed_at,true)}</time><span><b>{transitionVerb(transition)}</b><small>{transitionLabel(transition)}</small></span><ChevronRight size={15}/></button>)}</div>}
            <div className="snapshot-pick-row">{timeline.snapshots.map((capture,index)=><button key={capture.snapshot_id} className={snapshotId===capture.snapshot_id?"selected":""} aria-pressed={snapshotId===capture.snapshot_id} onClick={()=>{setSnapshotId(capture.snapshot_id);setInventoryPage(1)}}><span className="snapshot-dot"/><span><b>{snapshotName(index)} · {index===0?"First capture":index===timeline.snapshots.length-1?"Latest capture":"Intermediate capture"}</b><small>{date(capture.observed_at)} · {capture.objects_count.toLocaleString()} objects</small></span><ChevronRight size={16}/></button>)}</div>
          </section>
          <div className="category-strip">{primaryCounts.map(([cat,count])=><button key={cat} className={category===cat?"active":""} onClick={()=>{setCategory(category===cat?"":cat);setInventoryPage(1)}}><span>{labels[cat]||cat}</span><b>{Number(count).toLocaleString()}</b></button>)}</div>
          <div className="state-columns"><section className="panel inventory-panel"><div className="panel-heading"><div><span className="side-label">SNAPSHOT INVENTORY · {snapshotName(selectedSnapshotIndex).toUpperCase()} / {selectedSnapshotIndex===0?"FIRST":"CAPTURE"}</span><h3>{selectedSnapshotIndex===0?"Beginning endpoint state":selectedSnapshotIndex===timeline.snapshots.length-1?"Latest endpoint state":"Intermediate endpoint state"} <small>· {inventory?.total?.toLocaleString()||snapshot?.objects_count.toLocaleString()} {inventory?.total===1?"record":"records"}</small></h3></div><div className="table-tools"><select value={category} onChange={e=>{setCategory(e.target.value);setInventoryPage(1)}} aria-label="Category filter"><option value="">All categories</option>{Object.entries(labels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select><div className="mini-search"><Search size={13}/><input value={inventoryQuery} onChange={e=>{setInventoryQuery(e.target.value);setInventoryPage(1)}} placeholder="Filter objects"/></div></div></div><div className="inventory-table-wrap"><table className="inventory-table"><thead><tr><th>OBJECT</th><th>CATEGORY</th><th>STATUS / ATTRIBUTES</th></tr></thead><tbody>{(inventory?.items||[]).map((o:any)=><tr key={o.object_key}><td><b>{o.display_name}</b><small className="mono">{o.object_key}</small></td><td><span className="category-tag">{labels[o.category]||o.category}</span></td><td><InventoryAttributes attributes={o.attributes||{}}/></td></tr>)}</tbody></table><div className="table-foot inventory-pagination"><span>Showing {inventory?.total?((inventory.page-1)*inventory.page_size+1):0}–{Math.min((inventory?.page||1)*(inventory?.page_size||100),inventory?.total||0)} of {inventory?.total||0} records</span><div><button disabled={!inventory||inventory.page<=1} onClick={()=>setInventoryPage(p=>Math.max(1,p-1))}><ChevronLeft size={13}/></button><button disabled={!inventory||inventory.page*inventory.page_size>=inventory.total} onClick={()=>setInventoryPage(p=>p+1)}><ChevronRight size={13}/></button></div></div></div></section>
            <aside className="delta-column"><div className="panel delta-panel"><div className="delta-title-row"><div><span className="side-label">SNAPSHOT DELTA</span><h3>Differences between adjacent captures</h3>{caseData.id==="case-02"&&<p className="delta-guide">Expand the delta. The exact service name and executable path can pivot to Wazuh service or process records.</p>}</div><span className="delta-count">{timeline.deltas.length.toString().padStart(2,"0")}</span></div>{timeline.deltas.length?timeline.deltas.map(d=>{const expanded=expandedDeltaId===d.id,beforeIndex=Math.max(0,timeline.snapshots.findIndex(s=>s.snapshot_id===d.before_snapshot_id)),afterIndex=Math.max(0,timeline.snapshots.findIndex(s=>s.snapshot_id===d.after_snapshot_id)),item=timeline.investigations.find(candidate=>candidate.id===d.id),linked=(item?.transition_ids||[]).map(id=>timeline.transitions.find(t=>t.id===id)).filter(Boolean) as CSGTransition[];return <article className={`delta-item ${deltaId===d.id?"selected":""}`} key={d.id}><div className="delta-item-head"><span className={`operation-chip ${d.operation.toLowerCase()}`}>{snapshotChangeLabel(d)}</span><span>{labels[d.category]||d.category}</span><button className="delta-expand-toggle" type="button" aria-expanded={expanded} aria-label={`${expanded?"Hide":"Show"} details for ${d.object_key.split(":").slice(-1)[0]}`} onClick={()=>{selectInvestigation(d.id);setExpandedDeltaId(expanded?"":d.id)}}>{expanded?<ChevronDown size={15}/>:<ChevronRight size={14}/>}</button></div><b className="delta-object">{d.object_key.split(":").slice(-1)[0]}</b><div className="delta-compare"><div><small>{snapshotName(beforeIndex).toUpperCase()}</small><b>{formatState(d.before)}</b></div><ArrowRight size={13}/><div><small>{snapshotName(afterIndex).toUpperCase()}</small><b>{formatState(d.after)}</b></div></div><div className="delta-observation"><Clock3 size={12}/>{date(d.window.start)} → {date(d.window.end)}</div>{expanded&&<div className="delta-expanded-detail"><div className="delta-detail-fields"><section><b>{snapshotName(beforeIndex)} · Before</b><RecordFields value={d.before}/></section><section><b>{snapshotName(afterIndex)} · After</b><RecordFields value={d.after}/></section></div>{linked.length>0&&<div className="delta-linked-observations"><b>Related CSG observations</b>{linked.map(t=><div key={t.id}><time>{date(t.observed_at,true)}</time><span>{transitionVerb(t)} · {transitionDetails(t)}</span></div>)}</div>}</div>}</article>}):<div className="empty-delta"><Activity size={18}/><b>No Snapshot Delta in this case</b><p>Adjacent captures can agree even when CSG recorded activity that ended or returned to an earlier state between them.</p></div>}</div><EvidenceTray events={tray} onOpen={id=>void inspectEvent(id,"tray")} onRemove={toggleEvidence}/></aside>
            </div>
          <section className="panel transition-history"><div className="transition-history-head"><div><span className="side-label">SOURCE: CSG</span><h3>CSG State Change Timeline</h3><p>Changes CSG recorded across the snapshot window. Select a row to focus its investigation item.</p></div><span className="transition-count">{(timeline.transitions||[]).length.toString().padStart(2,"0")}</span></div>{timeline.transitions?.length?<div className="transition-list">{timeline.transitions.map((transition,index)=>{const item=timeline.investigations.find(candidate=>candidate.transition_ids.includes(transition.id));return <button id={`csg-transition-${transition.id}`} className={`transition-row ${focusedTransitionId===transition.id?"is-focused":""}`} key={transition.id} onClick={()=>{setFocusedTransitionId(transition.id);if(item)selectInvestigation(item.id)}}><span className="transition-sequence">{String(index+1).padStart(2,"0")}</span><span className="transition-time">{date(transition.observed_at,true)}</span><span className="transition-category">{transitionCategory(transition)}</span><span className="transition-object"><b>{transitionLabel(transition)}</b><small>{labels[transition.category]||transition.category} · {transition.object_key}</small></span><span className="transition-change"><b>{transitionVerb(transition)}</b><small>{transitionDetails(transition)}</small></span><span className="transition-source">CSG <ChevronRight size={12}/></span></button>})}</div>:<div className="transition-empty">No CSG state changes are listed for this case. Compare the inventories, then assess independent Windows/Wazuh telemetry.</div>}</section>
          <div className="state-next-row"><div><span className="hint-text">Ready to compare these observations with event logs?</span></div><button className="primary-action" onClick={()=>setView("wazuh")}>Investigate Wazuh events <ArrowRight size={15}/></button></div>
        </div>}

        {view==="wazuh"&&<div className="wazuh-view">
          <div className="wazuh-banner"><span className="wazuh-wordmark">wazuh</span><div className="wazuh-location"><span>Threat hunting</span><ChevronRight size={15}/><h2>Events</h2></div><span className="wazuh-source">Windows · Sysmon</span></div>
          <details className="search-playbook"><summary><BookOpen size={16}/><span><b>Search tips</b></span><ChevronDown size={15}/></summary><div className="search-playbook-grid"><div><i>01</i><b>Set the window</b><p>Click a chart bar for one minute, or drag across bars for a range.</p></div><div><i>02</i><b>Match the field</b><p>Service startup configuration and Running/Stopped status are different fields. Choose the event type that matches the CSG change.</p></div><div><i>03</i><b>Use exact identity</b><p>Try <code>service.name:&quot;&lt;name&gt;&quot;</code> for an exact service name. Free text can also return longer lookalike names.</p></div><div><i>04</i><b>Follow the evidence</b><p>Use process paths and PIDs to pivot between records. Read script content in order, then look for separate events that show what happened.</p></div></div></details>
        <div className="investigation-context"><label><GitBranch size={16}/> Evidence for <select aria-label="Active investigation item" value={deltaId} onChange={e=>selectInvestigation(e.target.value)}>{timeline.investigations.map(item=><option key={item.id} value={item.id}>{item.title}</option>)}</select></label><button onClick={()=>showStage("reconcile")}><Database size={15}/>{tray.length} collected<ChevronRight size={15}/></button></div>
          <div className="query-panel">
            <div className="query-label"><span>Search</span><small>Field:value · AND · OR · quote service.name for exact match</small></div>
            <div className="query-line"><Search size={17}/><input aria-label="Search events" value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>e.key==="Enter"&&void search(1)} maxLength={500} placeholder={`Search event text, or try host.name:"${caseData.host}"`}/><span className="live-search-state" aria-live="polite">{busy?<LoaderCircle size={12} className="spin"/>:<Activity size={12}/>} {busy?"Updating…":"Auto search"}</span></div>
            <div className="filter-line">
              <label><Filter size={13}/> CATEGORY <select aria-label="Event category" value={eventCategory} onChange={e=>setEventCategory(e.target.value)}><option value="">Any category</option>{eventCategories.map(c=><option key={c.value} value={c.value}>{c.label}</option>)}</select></label>
              <label>EVENT TYPE <select aria-label="Event type" value={eventType} onChange={e=>setEventType(e.target.value)}><option value="">Any event</option>{eventTypes.map(t=><option key={t} value={t}>{eventTypeLabels[t]||eventTypeLabel(t)}</option>)}</select></label>
              <label>EVENT ID <select aria-label="Windows event ID" value={eventCode} onChange={e=>setEventCode(e.target.value)}><option value="">Any ID</option>{eventCodes.map(code=><option key={code} value={code}>{code}</option>)}</select></label>
              <label>HOST <select aria-label="Event host" value={hostFilter} onChange={e=>setHostFilter(e.target.value)}><option value="">Any host</option>{filterHosts(caseData.host).map(host=><option key={host} value={host}>{host}</option>)}</select></label>
              <label>PROVIDER <select aria-label="Event provider" value={provider} onChange={e=>setProvider(e.target.value)}><option value="">Any provider</option>{eventProviders.map(name=><option key={name} value={name}>{name}</option>)}</select></label>
            </div>
            {(eventCategory==="service"||eventType.startsWith("service"))&&<div className="service-event-hint"><b>Service records</b><span>Compare the CSG field with the event operation. A startup setting and a Running/Stopped state do not mean the same thing.</span></div>}
            <div className="time-range-controls">
              <label>TIME PRESET <select aria-label="Time range preset" value={timePreset} onChange={e=>chooseTimePreset(e.target.value)}><option value="full">Full case window</option><option value="last5">Last 5 minutes</option><option value="last15">Last 15 minutes</option><option value="last30">Last 30 minutes</option><option value="last60">Last 1 hour</option><option value="custom">Custom range</option></select></label>
              <label>FROM <input aria-label="Start date and time" type="datetime-local" step="1" value={timeDraft.start} onChange={e=>editTimeBound("start",e.target.value)}/></label>
              <label>TO <input aria-label="End date and time" type="datetime-local" step="1" value={timeDraft.end} onChange={e=>editTimeBound("end",e.target.value)}/></label>
              <button className="clear-search-filters" onClick={clearEventFilters}><X size={12}/> Clear filters</button>
            </div>
            {(()=>{const start=fromLocalDateTime(timeDraft.start),end=fromLocalDateTime(timeDraft.end);return !start||!end||Date.parse(start)>Date.parse(end)?<div className="time-range-warning" role="status">Enter a valid start and end time in order. Results continue to use the last valid range.</div>:null})()}
          </div>
          <Histogram items={chartItems} range={timeRange} onSelectRange={(start,end)=>applyTimeRange(start,end,"custom")}/>
          <div className="active-filter-summary" aria-live="polite"><b>FILTERS</b>
            {query.trim()&&<button onClick={()=>setQuery("")} aria-label="Remove search query">Search: {query.trim()}<X size={12}/></button>}
            {eventCategory&&<button onClick={()=>setEventCategory("")} aria-label="Remove category filter">Category: {eventCategories.find(category=>category.value===eventCategory)?.label||eventCategory}<X size={12}/></button>}
            {eventType&&<button onClick={()=>setEventType("")} aria-label="Remove event type filter">Event type: {eventTypeLabel(eventType)}<X size={12}/></button>}
            {eventCode&&<button onClick={()=>setEventCode("")} aria-label="Remove event ID filter">Event ID: {eventCode}<X size={12}/></button>}
            {hostFilter&&<button onClick={()=>setHostFilter("")} aria-label="Remove host filter">Host: {hostFilter}<X size={12}/></button>}
            {provider&&<button onClick={()=>setProvider("")} aria-label="Remove provider filter">Provider: {provider}<X size={12}/></button>}
            {timeRange&&<span>Time: {date(timeRange.start,true)} – {date(timeRange.end,true)}</span>}
          </div>
          <div className="event-results"><div className="results-topline"><div><b>{(events?.total??0).toLocaleString()}</b> {events?.total===1?"matching event":"matching events"} <span>· Showing {events?.rows?.length?((events.page-1)*events.page_size+1):0}–{Math.min((events?.page||1)*(events?.page_size||100),events?.total||0)}</span></div><div><span className="page-size-label">100 ROWS / PAGE</span><button disabled={!events||events.page<=1||busy} onClick={()=>void search((events?.page||1)-1)}><ChevronLeft size={14}/></button><button disabled={!events||events.page*events.page_size>=events.total||busy} onClick={()=>void search((events?.page||1)+1)}><ChevronRight size={14}/></button></div></div>
            <div className="event-grid-head"><span>TIME ↓</span><span>EVENT ID</span><span>TYPE</span><span>HOST</span><span>PROCESS / OBJECT</span><span>COLLECT</span></div>
            <div className="event-list">{(events?.rows||[]).map((ev:EventRow)=><div className="event-result-item" key={ev.id}><div className={`event-row ${eventDetail?.id===ev.id?"open":""}`}><button className="event-row-main" aria-expanded={eventDetail?.id===ev.id&&detailSource==="results"} aria-controls={`event-detail-${ev.id}`} onClick={()=>eventDetail?.id===ev.id?closeEvent():void inspectEvent(ev.id)}><span className="event-time"><ChevronRight size={14} className="event-expand"/>{date(ev.timestamp,true)}</span><span className="event-id">{ev.event_code}</span><span className="event-type-cell"><i className={`event-type-mark ${ev.event_type.startsWith("service")?"service":ev.event_type.startsWith("registry")?"registry":""}`}/>{eventTypeLabel(ev.event_type)}{Number(ev.normalized?.rule?.level)>=10&&<b className="event-alert-level" aria-label={`High severity alert level ${ev.normalized.rule.level}`}>HIGH · L{ev.normalized.rule.level}</b>}</span><span className={ev.host_name===caseData.host?"host-same":"host-other"}>{ev.host_name}</span><span className="event-object">{ev.service_name||ev.process_name||ev.registry_key||ev.object_key}</span></button><button className={`event-collect ${selectedEventIds.has(ev.id)?"selected":""}`} aria-label={selectedEventIds.has(ev.id)?"Remove evidence":"Add to investigation"} onClick={()=>void toggleEvidence(ev)}>{selectedEventIds.has(ev.id)?<Check size={14}/>:<span>+</span>}</button></div>{eventDetail?.id===ev.id&&detailSource==="results"&&<EventDetails detailId={`event-detail-${ev.id}`} event={eventDetail} selected={selectedEventIds.has(eventDetail.id)} onToggle={()=>void toggleEvidence(eventDetail)} onClose={closeEvent} onFilter={filterFromEvent}/>}</div>)}{events&&!events.rows?.length&&<div className="empty-events"><Search size={21}/><b>No events match the current search and filters.</b><span>Adjust a filter or widen the time range.</span></div>}{!events&&<div className="empty-events"><LoaderCircle size={18} className="spin"/><b>Loading events…</b></div>}</div>
          </div>
          <div className="wazuh-note"><Clock3 size={13}/> Times shown in {Intl.DateTimeFormat().resolvedOptions().timeZone}</div>
        </div>}

        {view==="reconcile"&&<div className="reconcile-view">
          <div className="view-intro"><div><div className="section-kicker">RECONCILIATION WORKSHEET <span>· ANALYST SUBMISSION</span></div><h2>Does the evidence explain the state?</h2><p>Choose a finding for each item and explain the fields you checked.</p></div><span className="source-badge"><LockKeyhole size={14}/> FEEDBACK AFTER SUBMISSION</span></div>
          <div className="reconcile-layout"><section className="panel worksheet-panel"><div className="worksheet-target"><div><span className="side-label">ACTIVE INVESTIGATION ITEM</span><select value={deltaId} onChange={e=>selectInvestigation(e.target.value)}>{timeline.investigations.map(item=><option key={item.id} value={item.id}>{item.kind==="delta"?"Snapshot Delta":"CSG State Change Timeline"} · {item.title}</option>)}</select></div><span className="target-icon"><GitBranch size={17}/></span></div>
            {activeInvestigation?.kind==="transition"?<div className="observed-state-card transition-state-card"><span className="side-label">CSG STATE CHANGE TIMELINE</span><b>{activeInvestigation.title}</b>{activeTransitions.map(t=><div className="observed-transition-row" key={t.id}><span>{date(t.observed_at,true)} · {caseData.host}</span><div><b>{transitionVerb(t)}</b><small>{transitionDetails(t)}</small></div></div>)}<small>Source: CSG · compare with Windows/Wazuh telemetry as a separate evidence source.</small></div>:activeDelta?<div className="observed-state-card"><span className="side-label">SNAPSHOT DELTA · {snapshotName(activeDeltaBeforeIndex)} → {snapshotName(activeDeltaAfterIndex)}</span><b>{activeDelta.object_key.split(":").slice(-1)[0]}</b><div><span>{formatState(activeDelta.before)}</span><ArrowRight size={14}/><span>{formatState(activeDelta.after)}</span></div><small>{snapshotChangeLabel(activeDelta)} · {date(activeDelta.window.start)} to {date(activeDelta.window.end)}</small></div>:<div className="observed-state-card transient-card"><span className="side-label">CSG OBSERVATION</span><b>Process absent at both snapshot boundaries</b><div><span>Absent at {date(timeline.snapshots[0]?.observed_at||caseData.timeline_start)}</span><ArrowRight size={14}/><span>Absent at {date(timeline.snapshots[timeline.snapshots.length-1]?.observed_at||caseData.timeline_end)}</span></div><small>Use the CSG State Change Timeline, then compare it with independent Wazuh records.</small></div>}
            <div className="evidence-sheet"><div className="evidence-sheet-head"><div><span className="side-label">SELECTED EVENT EVIDENCE</span><b>{tray.length} record{tray.length===1?"":"s"} in the tray</b></div><button onClick={()=>setView("wazuh")}><Search size={13}/> Return to search</button></div>{tray.length?tray.map(e=><div className="evidence-sheet-row" key={e.id}><span className="evidence-code">{e.event_code}</span><div><b>{e.event_type} · {e.service_name||e.process_name||e.registry_key||e.object_key}</b><small>{date(e.timestamp,true)} · {e.host_name}</small></div><button onClick={()=>void toggleEvidence(e)} aria-label="Remove evidence"><X size={14}/></button></div>):<div className="empty-tray"><Database size={17}/> No events collected. If you found no matching record, explain what you searched.</div>}</div>
            <div className="classify-block"><span className="side-label">RECONCILIATION CLASSIFICATION</span><div className="classification-options">{statuses.map(s=><button key={s} onClick={()=>!reveal&&setClassification(s)} className={`${classification===s?"selected":""} status-${s.toLowerCase()}`} disabled={!!reveal}><i>{classification===s?<Check size={13}/>:<span/>}</i><b>{statusLabel(s)}</b><small>{statusCopy(s)}</small></button>)}</div></div>
            <label className="explanation-label">Analyst reasoning <span>{explanation.trim().length} characters · 20 minimum</span><textarea value={explanation} onChange={e=>setExplanation(e.target.value)} disabled={!!reveal} placeholder="Name the fields that match or conflict. If evidence is missing, describe what you searched." maxLength={3000}/></label>
            {!reveal&&<button className="submit-investigation" disabled={!classification||explanation.trim().length<20||busy} onClick={()=>void submit()}>{busy?<LoaderCircle size={15} className="spin"/>:<ShieldCheck size={16}/>} Submit reconciliation <ArrowRight size={15}/></button>}
            {reveal&&<Reveal result={reveal}/>}
          </section>
           <aside className="reconcile-side"><EvidenceTray events={tray} onOpen={id=>void inspectEvent(id,"tray")} onRemove={toggleEvidence}/></aside></div>
          {reveal&&<InstinctCheckpoint key={`${slug}-checkpoint`} slug={slug}/>}
        </div>}
        {view==="reconcile"&&slug==="final-investigation"&&cases.length>0&&cases.every(c=>c.completed)&&reveal&&<FinalSummary/>}
        <footer className="workspace-footer"><span>CSG ENDPOINT DETECTIVE</span><DeveloperCredit/></footer>
      </section>
    </div>
    {eventDetail&&detailSource==="tray"&&<EventDialog event={eventDetail} selected={selectedEventIds.has(eventDetail.id)} onToggle={()=>void toggleEvidence(eventDetail)} onClose={closeEvent} onFilter={filterFromEvent}/>}
  </main>
}

function formatState(value:Record<string,unknown>|null){if(!value)return "Not present";if(value.start_mode){const startType=String(value.start_mode).replace(/^./,c=>c.toUpperCase());return `Start type: ${startType}${value.status?` · Runtime status: ${String(value.status).replace(/^./,c=>c.toUpperCase())}`:""}`}if(value.service_name)return String(value.status||"Present");if(value.task_name)return "Scheduled task present";if(value.value_name)return "Run value present";if(value.local_port)return `${String(value.state||"Open")} · ${String(value.protocol||"TCP").toUpperCase()} ${value.local_address||"0.0.0.0"}:${value.local_port}`;return String(value.name||"Present")}
function snapshotChangeLabel(d:Delta){const before=d.before||{},after=d.after||{};if(d.category==="service"){if(d.operation==="MODIFY"&&before.start_mode!==after.start_mode)return "Service start type changed";return d.operation==="ADD"?"Service added":d.operation==="REMOVE"?"Service removed":"Service configuration changed"}if(d.category==="scheduled_task")return d.operation==="ADD"?"Scheduled task registered":d.operation==="REMOVE"?"Scheduled task deleted":"Scheduled task modified";if(d.category==="registry_autorun")return d.operation==="REMOVE"?"Registry value deleted":"Registry value set";if(d.category==="listener")return d.operation==="ADD"?"Listener opened":d.operation==="REMOVE"?"Listener closed":"Listener changed";return d.operation==="ADD"?"Added":d.operation==="REMOVE"?"Removed":"Modified"}
function InventoryAttributes({attributes}:{attributes:Record<string,unknown>}){const fields=Object.entries(attributes);return <div className="inventory-attributes">{fields.slice(0,5).map(([key,value])=><span className="attribute-inline" key={key}><i>{key.replaceAll("_"," ")}</i> {typeof value==="object"?JSON.stringify(value):String(value)}</span>)}{fields.length>5&&<details className="inventory-record-details"><summary>View {fields.length-5} more field{fields.length-5===1?"":"s"}</summary>{fields.slice(5).map(([key,value])=><span className="attribute-inline" key={key}><i>{key.replaceAll("_"," ")}</i> {typeof value==="object"?JSON.stringify(value):String(value)}</span>)}</details>}</div>}
function RecordFields({value}:{value:Record<string,unknown>|null}){if(!value)return <small>Object absent</small>;return <dl>{Object.entries(value).map(([key,field])=><div key={key}><dt>{key.replaceAll("_"," ")}</dt><dd>{typeof field==="object"?JSON.stringify(field):String(field)}</dd></div>)}</dl>}
function BriefingEvidenceMap({snapshots,deltas,onOpenCSG,onOpenWazuh}:{snapshots:Snapshot[];deltas:Delta[];onOpenCSG:(transitionId?:string)=>void;onOpenWazuh:()=>void}){
  const [step,setStep]=useState(0);
  const steps=[{name:"Snapshots",icon:Database},{name:"CSG timeline",icon:GitBranch},{name:"Wazuh logs",icon:FileSearch}];
  return <section className="evidence-tour panel" aria-labelledby="evidence-tour-title">
    <div className="tour-header"><span className="side-label">A QUICK TOUR</span><span>{String(step+1).padStart(2,"0")} / 03</span></div>
    <h2 id="evidence-tour-title">Meet your evidence.</h2>
    <div className="tour-tabs" role="group" aria-label="Explore evidence sources">{steps.map((source,index)=><button key={source.name} type="button" className={step===index?"active":""} aria-pressed={step===index} onClick={()=>setStep(index)}><source.icon size={16}/>{source.name}</button>)}</div>
    <div className="tour-content" key={step} aria-live="polite">
      {step===0&&<><div className="tour-snapshots tour-snapshots-many">{snapshots.map((capture,index)=><div key={capture.snapshot_id} className={`tour-snapshot ${index===snapshots.length-1?"after":""}`}><span>{snapshotName(index).toUpperCase()}</span><b>{capture.objects_count.toLocaleString()}</b><small>objects</small><time>{date(capture.observed_at)}</time></div>)}</div><h3>Compare adjacent captures</h3><p>Follow each interval in order: {snapshots.slice(0,-1).map((capture,index)=><span key={capture.snapshot_id}>{index?" · ":""}{String.fromCharCode(65+index)}→{String.fromCharCode(66+index)}</span>)}. This case has <strong>{deltas.length} Snapshot Delta{deltas.length===1?"":"s"}</strong> across {Math.max(0,snapshots.length-1)} intervals.</p><button className="tour-open" onClick={()=>onOpenCSG()}>Compare snapshots<ArrowRight size={15}/></button></>}
      {step===1&&<><div className="tour-transition"><div className="tour-record-title"><span className="side-label">CSG STATE SOURCE</span><span>Independent observations</span></div><b>Endpoint changes between captures</b><p>Open CSG State to inspect this case’s records and compare them with the snapshots.</p></div><h3>Start with endpoint state</h3><p>Snapshot Delta and the CSG timeline show different views of endpoint activity. Use the recorded fields to form your own search pivots.</p><button className="tour-open" onClick={()=>onOpenCSG()}>Inspect CSG state<ArrowRight size={15}/></button></>}
      {step===2&&<><div className="tour-log-schema"><div><Terminal size={15}/><span>FIELDS TO CHECK</span></div>{[["host.name","Same endpoint"],["event.id","What was recorded"],["object fields","Same service, process, task, or value"],["timestamp","Inside the case window"]].map(([field,meaning])=><div key={field}><code>{field}</code><span>{meaning}</span></div>)}</div><h3>Do the logs support the CSG record?</h3><p>Search the archive, inspect the raw event, and check the values. Matching times alone are not enough.</p><button className="tour-open" onClick={onOpenWazuh}>Open Wazuh events<ArrowRight size={15}/></button></>}
    </div>
    <div className="tour-footer"><span>Select a source to explore.</span><div><button aria-label="Previous evidence source" disabled={step===0} onClick={()=>setStep(index=>index-1)}><ChevronLeft size={16}/></button><button aria-label="Next evidence source" disabled={step===2} onClick={()=>setStep(index=>index+1)}><ChevronRight size={16}/></button></div></div>
  </section>
}
type InstinctOption={id:"a"|"b";label:string;correct:boolean};
type InstinctQuestion={topic:string;prompt:string;options:[InstinctOption,InstinctOption];correctFeedback:string;reviewFeedback:string};
const instinctQuestions:Record<string,InstinctQuestion>={
  "expected-service":{topic:"Corroborating evidence",prompt:"CSG shows a new service and the SIEM shows that same service being created at about the same time. What does this give the analyst?",options:[{id:"a",label:"Proof that the service is legitimate.",correct:false},{id:"b",label:"Corroborating evidence that strengthens the investigation timeline.",correct:true}],correctFeedback:"Right. Matching host, service identity, installation details, and time make the two sources corroborate the same change. That supports the timeline; it does not establish that the service is benign.",reviewFeedback:"A matching creation event supports the CSG finding; it does not prove the service is legitimate. Check the host and service details, then use process and script evidence to assess intent."},
  "missing-service-event":{topic:"Missing telemetry",prompt:"Security events suddenly stop appearing during suspicious activity. Does that mean the activity stopped?",options:[{id:"a",label:"Yes. No events means nothing happened.",correct:false},{id:"b",label:"No. Telemetry may have been interrupted, disabled, or suppressed.",correct:true}],correctFeedback:"Right. An event gap describes what was collected, not everything that happened. Compare independent state evidence and collection coverage before drawing a conclusion.",reviewFeedback:"An event gap is not proof that activity stopped. Compare independent state evidence with the available collection and surrounding records."},
  "complete-state-model":{topic:"Events without persistent state",prompt:"The SIEM records a suspicious process execution, but the next CSG snapshot shows no new process or service. Was the alert useless?",options:[{id:"a",label:"Yes. Nothing remained on the system.",correct:false},{id:"b",label:"No. Short-lived malicious activity may appear in events without leaving persistent state.",correct:true}],correctFeedback:"Right. The process started and exited between captures. CSG’s timeline and Sysmon process events preserve that lifecycle even though the next inventory has no process entry.",reviewFeedback:"A later snapshot describes state at capture time. A process can execute and exit between captures; use the CSG timeline and process start/exit events to investigate it."},
  "staged-relay":{topic:"Snapshot changes",prompt:"A service changes from Manual start to Automatic between two CSG snapshots. Is that important?",options:[{id:"a",label:"No. The service still has the same name.",correct:false},{id:"b",label:"Yes. Configuration changes can indicate persistence or unauthorized modification.",correct:true}],correctFeedback:"Right. Compare the exact service, host, and direction of change. In this case, the service image and process ancestry link the configuration change to the later task and listener.",reviewFeedback:"A stable name does not mean stable configuration. Check the before/after start mode and then trace the service image and child activity for context."},
  "final-investigation":{topic:"State vs. events",prompt:"CSG finds a persistent scheduled task, but the SIEM has no task-registration event. What should you conclude?",options:[{id:"a",label:"No SIEM event means the task is safe.",correct:false},{id:"b",label:"Investigate the mismatch: persistent state exists without supporting telemetry.",correct:true}],correctFeedback:"Right. CSG confirms the task persists, while the archive lacks a matching Task Scheduler 106. The exact task/action in PowerShell 4104 links it to the incident, but does not replace the missing registration event.",reviewFeedback:"Missing telemetry does not make persistent state safe. Compare the task and action with available process/script evidence, and report the absent registration event as a gap."}
};
function InstinctCheckpoint({slug}:{slug:string}){
  const question=instinctQuestions[slug]||instinctQuestions["expected-service"];
  const [answer,setAnswer]=useState<"a"|"b"|null>(null);
  const selected=question.options.find(option=>option.id===answer);
  const correct=selected?.correct===true;
  return <details className="briefing-check panel"><summary><CircleHelp size={18}/><span><b>Test your instinct</b><small>{question.topic} · one question</small></span><ChevronDown size={17}/></summary><div className="checkpoint-content"><h3>{question.prompt}</h3><div className="briefing-check-options" role="group" aria-label={question.topic}>{question.options.map(option=><button key={option.id} type="button" className={answer===option.id?(option.correct?"selected-correct":"selected-review"):""} aria-pressed={answer===option.id} onClick={()=>setAnswer(option.id)}>{option.label}</button>)}</div>{answer&&<div className={`briefing-check-feedback ${correct?"correct":"review"}`} role="status">{correct?<Check size={18}/>:<CircleHelp size={18}/>}<p>{correct?question.correctFeedback:question.reviewFeedback}</p></div>}</div></details>
}
function transitionCategory(t:CSGTransition){return ({service:"SERVICE",process:"PROCESS",listener:"LISTENER",scheduled_task:"SCHEDULED TASK",registry_autorun:"REGISTRY"} as Record<string,string>)[t.category]||t.category.toUpperCase()}
function transitionLabel(t:CSGTransition){const value=t.after||t.before||{};return String(value.service_name||value.name||value.task_name||value.value_name||value.process_name||t.object_key.split(":").slice(-1)[0])}
function transitionVerb(t:CSGTransition){const before=t.before||{},after=t.after||{};if(t.category==="service")return before.start_mode!==undefined||after.start_mode!==undefined?"Service start type changed":"Service configuration changed";if(t.category==="process")return t.transition==="START"?"Process Create":t.transition==="EXIT"?"Process Terminated":"Process state changed";if(t.category==="listener")return t.transition==="OPEN"?"Listener Opened":t.transition==="CLOSE"?"Listener Closed":"Listener state changed";if(t.category==="scheduled_task")return t.transition==="CREATE"||t.transition==="ADD"?"Scheduled Task Registered":t.transition==="REMOVE"?"Scheduled Task Deleted":"Scheduled Task Modified";if(t.category==="registry_autorun")return t.transition==="REMOVE"?"Registry Value Deleted":"Registry Value Set";return `${transitionCategory(t)} state changed`}
function transitionDetails(t:CSGTransition){const value=t.after||t.before||{};const host=`Host: ${t.host}`;if(t.category==="service"){const before=t.before||{},after=t.after||{};return [before.start_mode!==undefined&&after.start_mode!==undefined?`Start type: ${String(before.start_mode).replace(/^./,c=>c.toUpperCase())} → ${String(after.start_mode).replace(/^./,c=>c.toUpperCase())}`:"Field: Start type",before.start_mode!==undefined?`Previous value: ${String(before.start_mode).replace(/^./,c=>c.toUpperCase())}`:null,after.start_mode!==undefined?`New value: ${String(after.start_mode).replace(/^./,c=>c.toUpperCase())}`:null,value.status?`Runtime status: ${value.status}`:null,host].filter(Boolean).join(" · ")}if(t.category==="process")return [`Image path: ${value.executable_path}`,`PID: ${value.pid}`,value.parent?`Parent: ${value.parent}`:null,value.ppid?`PPID: ${value.ppid}`:null,host].filter(Boolean).join(" · ");if(t.category==="listener")return [`Protocol: ${String(value.protocol||"TCP").toUpperCase()}`,value.local_address?`Local address: ${value.local_address}`:null,value.local_port?`Local port: ${value.local_port}`:null,value.pid?`PID: ${value.pid}`:null,value.process_name?`Process image: ${value.process_name}`:null,value.executable_path?`Image path: ${value.executable_path}`:null,host].filter(Boolean).join(" · ");if(t.category==="scheduled_task"){const action=String(value.action||"");return [`Task name: ${value.task_name}`,value.task_name?`Task path: ${value.task_name}`:null,action?`Action: ${action}`:null,action?`Executable: ${action.split(" ")[0]}`:null,value.run_as?`Run as: ${value.run_as}`:null,host].filter(Boolean).join(" · ")}if(t.category==="registry_autorun"){const process=t.after?.process_name||t.after?.process;return [value.registry_key?`Registry path: ${value.registry_key}`:null,value.value_name?`Value name: ${value.value_name}`:null,value.value_data?`Value data: ${value.value_data}`:null,process?`Process: ${process}`:null,host].filter(Boolean).join(" · ")}return [transitionLabel(t),host].filter(Boolean).join(" · ")}

function statusCopy(s:string){return ({CONSISTENT:"The logs support the observed change.",PARTIALLY_EXPLAINED:"The logs explain part of the recorded sequence.",UNEXPLAINED:"You found no matching event for the observed change.",CONTRADICTED:"A log in the same context conflicts with the CSG values.",INSUFFICIENT_EVIDENCE:"The records cannot support a reliable finding."} as any)[s]}

function EvidenceTray({events,onOpen,onRemove}:{events:EventRow[];onOpen:(id:string)=>void;onRemove:(e:EventRow)=>void}){return <div className="panel evidence-tray"><div className="tray-title"><div><span className="side-label">EVIDENCE TRAY</span><b>Collected records</b></div><span>{events.length.toString().padStart(2,"0")}</span></div>{events.length?events.map(e=><div className="tray-event" key={e.id}><button className="tray-event-main" onClick={()=>onOpen(e.id)}><i/><span><b>{e.event_type}</b><small>{e.service_name||e.process_name||e.registry_key||e.object_key}</small><small>{date(e.timestamp,true)} · {e.event_code}</small></span></button><button className="tray-remove" onClick={()=>onRemove(e)} aria-label="Remove selected event"><X size={13}/></button></div>):<div className="tray-empty">Events you collect from the console appear here and stay linked to this investigation item.</div>}</div>}

function Histogram({items,range,onSelectRange}:{items:{time:string;end:string;count:number}[];range:{start:string;end:string}|null;onSelectRange:(start:string,end:string)=>void}){const max=Math.max(1,...items.map(x=>x.count));const dragStart=useRef<number|null>(null);const dragLast=useRef<number|null>(null);const didMove=useRef(false);const suppressClick=useRef(false);const[draftRange,setDraftRange]=useState<[number,number]|null>(null);function indexAt(clientX:number,element:HTMLElement){const rect=element.getBoundingClientRect();return Math.max(0,Math.min(items.length-1,Math.floor(((clientX-rect.left)/Math.max(1,rect.width))*items.length)))}function moveDrag(clientX:number,element:HTMLElement){if(dragStart.current===null||!items.length)return;const index=indexAt(clientX,element);if(index!==dragLast.current)didMove.current=true;dragLast.current=index;setDraftRange([Math.min(dragStart.current,index),Math.max(dragStart.current,index)])}function finishDrag(clientX:number,element:HTMLElement){if(dragStart.current===null)return;moveDrag(clientX,element);const first=Math.min(dragStart.current,dragLast.current??dragStart.current),last=Math.max(dragStart.current,dragLast.current??dragStart.current);if(items[first]&&items[last]){onSelectRange(items[first].time,items[last].end);suppressClick.current=true;window.setTimeout(()=>{suppressClick.current=false},0)}dragStart.current=null;dragLast.current=null;didMove.current=false;setDraftRange(null)}return <div className="histogram-panel"><div className="histogram-head"><span><Activity size={14}/> EVENT VOLUME</span><small>DRAG TO SELECT A TIME RANGE · 1-MINUTE BUCKETS</small></div><div className="histogram-bars" role="group" aria-label="Event volume by minute" onPointerDown={e=>{if(!items.length)return;const index=indexAt(e.clientX,e.currentTarget);dragStart.current=index;dragLast.current=index;didMove.current=false;e.currentTarget.setPointerCapture(e.pointerId);setDraftRange([index,index])}} onPointerMove={e=>moveDrag(e.clientX,e.currentTarget)} onPointerUp={e=>finishDrag(e.clientX,e.currentTarget)}>{items.map((item,i)=>{const inAppliedRange=!!range&&Date.parse(item.time)<Date.parse(range.end)&&Date.parse(item.end)>Date.parse(range.start);const inDraft=!!draftRange&&i>=draftRange[0]&&i<=draftRange[1];const highlighted=draftRange?inDraft:inAppliedRange;return <button type="button" key={item.time} className={`histogram-bar ${highlighted?"selected":""} ${range&&!draftRange&&!inAppliedRange?"outside-range":""}`} title={`${date(item.time,true)}–${date(item.end,true)} · ${item.count} events`} style={{height:`${Math.max(2,Math.round(item.count/max*42))}px`}} onClick={e=>{if(suppressClick.current){e.preventDefault();return}onSelectRange(item.time,item.end)}} aria-label={`${item.count} events from ${date(item.time,true)} to ${date(item.end,true)}; select this minute`}/>})}</div><div className="histogram-axis"><span>{date(items[0]?.time||new Date().toISOString()).split(", ").pop()}</span><span>{items[Math.floor(items.length/2)]?date(items[Math.floor(items.length/2)].time).split(", ").pop():""}</span><span>{date(items[items.length-1]?.end||new Date().toISOString()).split(", ").pop()}</span></div></div>}

function EventDialog({event,selected,onToggle,onClose,onFilter}:{event:EventRow;selected:boolean;onToggle:()=>void;onClose:()=>void;onFilter:(field:"host"|"event_code",value:string)=>void}){
  const dialogRef=useRef<HTMLDialogElement>(null);
  useEffect(()=>{
    const dialog=dialogRef.current;
    const previousFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;
    dialog?.showModal();
    return()=>{dialog?.close();if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true})};
  },[]);
  return <dialog ref={dialogRef} className="event-dialog" aria-label="Collected event details" onCancel={event=>{event.preventDefault();onClose()}} onClick={event=>{if(event.target===event.currentTarget)onClose()}}><EventDetails key={event.id} event={event} selected={selected} onToggle={onToggle} onClose={onClose} onFilter={onFilter}/></dialog>
}
function EventDetails({event,selected,onToggle,onClose,onFilter,detailId}:{event:EventRow;selected:boolean;onToggle:()=>void;onClose:()=>void;onFilter:(field:"host"|"event_code",value:string)=>void;detailId?:string}){
  const [showRaw,setShowRaw]=useState(false);
  return <aside id={detailId} className="event-detail-drawer">
    <div className="drawer-head"><div><span className="side-label">EVENT DETAILS</span><b>{eventTypeLabel(event.event_type)}</b></div><button onClick={onClose} aria-label="Close event details"><X size={18}/></button></div>
    <div className="detail-summary"><div><small>TIMESTAMP</small><b>{date(event.timestamp,true)}</b></div><div><small>HOST</small><b>{event.host_name}</b></div><div><small>WINDOWS EVENT ID</small><b>{event.event_code}</b></div><div><small>PROVIDER</small><b>{event.provider}</b></div></div>
    <div className="detail-actions"><button onClick={()=>onFilter("host",event.host_name)}><Filter size={14}/> Filter this host</button><button onClick={()=>onFilter("event_code",event.event_code)}><Filter size={14}/> Filter this event ID</button></div>
    <div className="provenance-chip"><span>RECORD SOURCE</span><b>{event.provenance==="redacted_research_structure"?"Sanitized reference structure":event.provenance==="synthetic_attack_context"?"Synthetic attack scenario":"Generated classroom event"}</b></div>
    {event.normalized?.message&&<p className="event-message">{String(event.normalized.message)}</p>}
    <div className="detail-fields">{Object.entries(event.normalized||{}).filter(([key])=>!["event","host","timestamp","message"].includes(key)).map(([group,value])=><div className="detail-group" key={group}><span>{group.replaceAll("_"," ")}</span>{typeof value==="object"&&value?Object.entries(value as object).map(([key,field])=><div key={key}><small>{key.replaceAll("_"," ")}</small><b>{typeof field==="object"?JSON.stringify(field):String(field)}</b></div>):<b>{String(value)}</b>}</div>)}</div>
    <button className="raw-toggle" aria-expanded={showRaw} onClick={()=>setShowRaw(!showRaw)}><Code2 size={16}/>{showRaw?"Hide":"View"} raw event JSON<ChevronDown size={16}/></button>{showRaw&&<pre className="raw-json">{JSON.stringify(event.raw||{},null,2)}</pre>}
    <button className={`drawer-collect ${selected?"selected":""}`} onClick={onToggle}>{selected?<Check size={17}/>:<span>+</span>}{selected?"Collected · click to remove":"Add to investigation"}</button>
  </aside>
}

function Reveal({result}:{result:any}){return <section className="reveal-card"><div className="reveal-top"><span className="reveal-icon"><ShieldCheck size={19}/></span><div><span className="side-label">CYBERSTATEGUARDIAN RECONCILIATION</span><h3>{result.correct?"Finding saved":"Review your evidence"}</h3></div><b className={result.correct?"score-correct":"score-review"}>{result.score}<small>/ 100</small></b></div><div className="reveal-compare"><div><small>YOUR CLASSIFICATION</small><b>{statusLabel(result.student_classification)}</b></div><ArrowRight size={15}/><div><small>CSG RESULT</small><b>{statusLabel(result.csg_classification)}</b></div><span className={result.correct?"result-pill good":"result-pill review"}>{result.correct?"CORRECT":"PARTIAL / REVIEW"}</span></div><p>{result.csg_explanation}</p>{result.evidence_review?.length>0&&<div className="evidence-review-list">{result.evidence_review.map((x:any)=><div key={x.event_id}><span className={x.accepted?"accepted-mark":"rejected-mark"}>{x.accepted?<Check size={13}/>:<X size={13}/>}</span><span><b>{x.event_type} · {x.object_key}</b><small>{x.reason}</small></span></div>)}</div>}<div className="learning-note"><b>WHY THIS MATTERS</b><span>{result.learning_note}</span></div></section>}

function FinalSummary(){return <section className="final-summary panel"><div className="section-kicker">LAB COMPLETE <span>· CYBERSTATEGUARDIAN CONCEPTS</span></div><h2>What did you reconstruct?</h2><p>The incident includes endpoint state that persisted, CSG-observed activity between snapshots, and Wazuh evidence with different coverage.</p><div className="summary-diagram"><div><span>WHAT PERSISTED</span><b>Snapshot Delta</b></div><ArrowDownRight size={17}/><div><span>WHAT HAPPENED BETWEEN</span><b>CSG State Change Timeline</b></div><ArrowDownRight size={17}/><div><span>EVENT CORROBORATION</span><b>Wazuh</b></div><ArrowDownRight size={17}/><div className="summary-reconcile"><span>ANALYST</span><b>Reconciliation</b></div></div><ol>{["Confirmed the task and Run value persisted into Snapshot B.","Found the service start-type change and restoration in the CSG State Change Timeline.","Linked the process to the configured service binary by path and parent.","Linked the temporary listener to that process by PID and executable.","Confirmed process start and exit with Wazuh records.","Used the WFP event as partial listener corroboration.","Followed the child PowerShell process to commands naming the task and Run value.","Connected Defender disablement, archive creation, and outbound activity to that process.","Rejected same-time events with the wrong host, identity, or values.","Explained the missing task-registration record while retaining the CSG-to-script link.","Compared independent sources without treating proximity as proof."].map((step,i)=><li key={step}><i>{String(i+1).padStart(2,"0")}</i>{step}</li>)}</ol><div className="summary-callout"><ShieldCheck size={17}/><span><b>Snapshots show endpoint state at two boundaries. Snapshot Delta shows what remained different. CSG State Change Timeline shows selected activity between them.</b><small>Match Wazuh by identity and operation; use script content and process ancestry to connect malicious intent to observed state.</small></span></div></section>}
